#include <vector>
#include <omp.h>

bool contains(std::vector<int> const& x, int target) {
    const int n = static_cast<int>(x.size());
    bool found = false;

    #pragma omp parallel for default(none) shared(x, target, n) reduction(||:found)
    for (int i = 0; i < n; ++i) {
        found = found || (x[i] == target);
    }

    return found;
}
